<?php use App\Services\History; ?>
<div class="page-heading"><div><div class="eyebrow">WORKSPACE RECORDS</div><h1>Publishing History</h1><p>Local history management never deletes WordPress posts or media.</p></div><?php if((int)$user['role_id']===1): ?><form method="post" action="<?= e(local_url('/history/clear')) ?>" data-history-form data-kind="clear" data-count="<?= e($historySnapshot['count']) ?>"><?= csrf() ?><input type="hidden" name="confirmed" value="0"><input type="hidden" name="snapshot_token" value="<?= e($historySnapshot['token']) ?>"><button class="btn btn-outline-danger" type="button" data-history-open <?= $historySnapshot['count']?'':'disabled' ?>>Clear History</button></form><?php endif; ?></div>
<div class="alert phase-alert">Delete and Clear History remove local history entries from this view only. Active drafts, files, remote IDs and audit records are retained. New publishing activity will appear again.</div>
<?php $historyRows=$rows;$showDelete=true;require ROOT.'/app/Views/history-announcements.php'; ?>
<?php if($active): ?><h2 class="mt-4 mb-3">Active drafts and pending work</h2><p class="small text-secondary">These announcements remain available even though their history entries were cleared.</p><?php $historyRows=$active;$showDelete=false;require ROOT.'/app/Views/history-announcements.php'; endif; ?>
<h2 class="mt-4 mb-3">Publishing events</h2><div class="surface table-responsive"><table class="table"><thead><tr><th>Announcement</th><th>Status</th><th>Publisher</th><th>Result</th><th>Time (UTC)</th><th>Actions</th></tr></thead><tbody><?php foreach($history as $h): ?><tr data-history-event="<?= e($h['id']) ?>"><td><?= e($h['title']) ?></td><td><?= e($h['status']) ?></td><td><?= e($h['author']) ?></td><td><?= e($h['message']) ?><?php if($h['wordpress_post_id']): ?> · #<?= e($h['wordpress_post_id']) ?><?php endif; ?></td><td><?= e($h['created_at']) ?></td><td><?php if(History::canDelete($user,(int)$h['user_id'])): ?><form method="post" action="<?= e(local_url('/history/delete')) ?>" data-history-form data-kind="delete"><?= csrf() ?><input type="hidden" name="confirmed" value="0"><input type="hidden" name="kind" value="event"><input type="hidden" name="id" value="<?= e($h['id']) ?>"><button class="btn btn-sm btn-outline-danger" type="button" data-history-open>Delete</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$history): ?><tr><td colspan="6" class="text-secondary p-4">No publishing events recorded.</td></tr><?php endif; ?></tbody></table></div>
<dialog id="history-dialog" aria-labelledby="history-dialog-title"><div class="form-panel"><h2 id="history-dialog-title">Delete local history</h2><p id="history-confirm-text"></p><p class="small text-secondary">This removes local history entries only. It does not delete WordPress posts or media. Active drafts, poster files, synchronization identifiers and audit records are preserved.</p><div class="form-actions"><button class="btn btn-danger" type="button" id="history-confirm">Confirm deletion</button><button class="btn btn-light" type="button" id="history-cancel">Cancel</button></div></div></dialog>
